SELECT id, username, password, real_name, phone, email, role, enabled, created_at, updated_at
FROM sys_user
WHERE id = #{id}

SELECT id, username, password, real_name, phone, email, role, enabled, created_at, updated_at
FROM sys_user
WHERE username = #{username}

